import { describe, expect, it } from "vitest";
import { shout } from "./volume";

describe("shout", () => {
  it("uppercases lowercase text", () => {
    expect(shout("hello")).toBe("HELLO");
  });

  it("keeps already uppercase text unchanged", () => {
    expect(shout("HELLO")).toBe("HELLO");
  });

  it("uppercases mixed-case text", () => {
    expect(shout("Hello, World! 123")).toBe("HELLO, WORLD! 123");
  });

  it("returns an empty string for empty input", () => {
    expect(shout("")).toBe("");
  });
});

